215	function initStoryStatsObserver(): void {
216	  const container = document.querySelector<HTMLElement>(STORY_STATS_SELECTOR);
217	  if (!container) return;
218	  const observer = new IntersectionObserver(
219	    (entries) => {
220	      const entry = entries[0];
221	      if (!entry?.isIntersecting) return;
222	      if (mainSceneDomState.storyStatsFired) return;
223	      mainSceneDomState.storyStatsFired = true;
224	      observer.disconnect();
225	      triggerStoryStats();
226	    },
227	    { threshold: 0.35 },
228	  );
229	  observer.observe(container);
230	}
