319	(function initPortfolioHover(): void {
320	  const items = document.querySelectorAll<HTMLLIElement>(
321	    ".no-main-portfolio__item[data-video]",
322	  );
323	  items.forEach((li) => {
324	    const videoUrl = li.dataset.video || MAIN_PORTFOLIO_FALLBACK_VIDEO;
325	    const figure = li.querySelector<HTMLElement>(".no-sub-gallery-item__img");
326	    const video = li.querySelector<HTMLVideoElement>("video");
327	    if (!figure || !video) return;
328	
329	    let isHovered = false;
330	    let pendingPlay: Promise<void> | null = null;
331	
332	    const show = (): void => {
333	      if (isHovered) figure.classList.add("is-video-active");
334	    };
335	    const hideNow = (): void => {
336	      figure.classList.remove("is-video-active");
337	    };
338	    const safePause = (): void => {
339	      video.pause();
340	      video.currentTime = 0;
341	    };
342	    const drainAndPause = (): void => {
343	      const p = pendingPlay;
344	      pendingPlay = null;
345	      if (p !== null) {
346	        void p.then(() => {
347	          if (!isHovered) safePause();
348	        });
349	      } else {
350	        safePause();
351	      }
352	    };
353	
354	    const onEnter = (): void => {
355	      isHovered = true;
356	      if (!video.src) {
357	        video.src = videoUrl;
358	        video.load();
359	      }
360	      pendingPlay = video.play().catch(() => undefined);
361	      if (video.readyState >= 3) {
362	        show();
363	      } else {
364	        video.addEventListener("canplay", show, { once: true });
365	      }
366	    };
367	    const onLeave = (): void => {
368	      isHovered = false;
369	      video.removeEventListener("canplay", show);
370	      hideNow();
371	      drainAndPause();
372	    };
373	
374	    li.addEventListener("pointerenter", onEnter);
375	    li.addEventListener("pointerleave", onLeave);
376	    _portfolioHoverCleanups.push(() => {
377	      isHovered = false;
378	      video.removeEventListener("canplay", show);
379	      figure.classList.remove("is-video-active");
380	      drainAndPause();
381	      li.removeEventListener("pointerenter", onEnter);
382	      li.removeEventListener("pointerleave", onLeave);
383	    });
384	  });
385	})();
