425	function syncContactHead(progress: number): void {
426	  // Keep the contact panel visible through the footer zone and hide it only
427	  // when the scene is left or rewound before the reveal threshold.
428	  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;
429	  const actionsChanged = mainSceneDomState.isContactActionsVisible !== shouldShow;
430	  const headChanged = mainSceneDomState.isContactHeadVisible !== shouldShow;
431	  if (!actionsChanged && !headChanged) return;
432	  const section = getContactSection();
433	  const head = getContactHead();
434	  const actions = getContactActions();
435	  if (!section || !head || !actions) return;
436	  const textItems = getContactTextItems();
437	  const actionItems = getContactActionItems();
438	
439	  if (actionsChanged) {
440	    mainSceneDomState.isContactActionsVisible = shouldShow;
441	    mainSceneDomState.contactActionTimers = clearTimers(
442	      mainSceneDomState.contactActionTimers,
443	    );
444	    const queue = shouldShow ? actionItems : actionItems.slice().reverse();
445	    const delayStep = shouldShow
446	      ? CONTACT_HEAD_TRANSITION.revealStagger
447	      : CONTACT_HEAD_TRANSITION.hideStagger;
448	    queue.forEach((item, index) => {
449	      const timerId = window.setTimeout(
450	        () => {
451	          item.classList.add(INIT_DOM_CLASSES.blockBase);
452	          item.classList.remove(INIT_DOM_CLASSES.boxHidden);
453	          if (shouldShow) {
454	            item.classList.remove("is-block-reveal-down");
455	            BlockReveal.reveal(item);
456	            return;
457	          }
458	          item.classList.remove(INIT_DOM_CLASSES.blockUp);
459	          item.classList.add("is-block-reveal-down");
460	        },
461	        index * delayStep * 1000,
462	      );
463	      mainSceneDomState.contactActionTimers.push(timerId);
464	    });
465	  }
466	
467	  if (!headChanged) return;
468	  mainSceneDomState.isContactHeadVisible = shouldShow;
469	  mainSceneDomState.contactHeadTimers = clearTimers(
470	    mainSceneDomState.contactHeadTimers,
471	  );
472	
473	  if (shouldShow) {
474	    section.dataset.active = "true";
475	    head.dataset.active = "true";
476	    actions.dataset.active = "true";
477	    TextReveal.setVisibleOff(textItems);
478	    textItems.forEach((item, index) => {
479	      const timerId = window.setTimeout(
480	        () => {
481	          TextReveal.setVisibleOn(item);
482	        },
483	        index * CONTACT_HEAD_TRANSITION.revealStagger * 1000,
484	      );
485	      mainSceneDomState.contactHeadTimers.push(timerId);
486	    });
487	    return;
488	  }
489	
490	  textItems
491	    .slice()
492	    .reverse()
493	    .forEach((item, index) => {
494	      const timerId = window.setTimeout(
495	        () => {
496	          TextReveal.setVisibleOff(item);
497	        },
498	        index * CONTACT_HEAD_TRANSITION.hideStagger * 1000,
499	      );
500	      mainSceneDomState.contactHeadTimers.push(timerId);
501	    });
502	
503	  const hideTimerId = window.setTimeout(
504	    () => {
505	      section.dataset.active = "false";
506	      head.dataset.active = "false";
507	      actions.dataset.active = "false";
508	    },
509	    (Math.max(textItems.length - 1, 0) *
510	      CONTACT_HEAD_TRANSITION.hideStagger +
511	      CONTACT_HEAD_TRANSITION.hideSettleDuration) *
512	      1000,
513	  );
514	  mainSceneDomState.contactHeadTimers.push(hideTimerId);
515	}
